import{_ as d,a0 as o,w as l,s as r,ao as t,I as i,x as a,a1 as n,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"Linux 中 4 个简单的找出进程 ID（PID）的方法 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 中 4 个简单的找出进程 ID（PID）的方法 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 中 4 个简单的找出进程 ID（PID）的方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 中 4 个简单的找出进程 ID（PID）的方法 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171219 4 Easiest Ways To Find Out Process ID (PID) In Linux","title":"Linux 中 4 个简单的找出进程 ID（PID）的方法","tag":"201802","desc":""},"relativePath":"201802/20171219 4 Easiest Ways To Find Out Process ID (PID) In Linux.md","filePath":"[post].md"}'),c={name:"201802/20171219 4 Easiest Ways To Find Out Process ID (PID) In Linux.md"};function h(u,s,g,k,D,I){const e=o("Link");return l(),r("div",null,[s[16]||(s[16]=t('<h1 id="linux-中-4-个简单的找出进程-id-pid-的方法" tabindex="-1">Linux 中 4 个简单的找出进程 ID（PID）的方法 <a class="header-anchor" href="#linux-中-4-个简单的找出进程-id-pid-的方法" aria-label="Permalink to “Linux 中 4 个简单的找出进程 ID（PID）的方法”">​</a></h1><p>每个人都知道 PID，究竟什么是 PID？为什么你想要 PID？你打算用 PID 做什么？你脑子里有同样的问题吗？如果是这样，你就找对地方了解这些细节了。</p><p>我们查询 PID 主要是用来杀死一个没有响应的程序，它类似于 Windows 任务管理器一样。 Linux GUI 也提供相同的功能，但 CLI 是执行 <code>kill</code> 操作的有效方法。</p><h3 id="什么是进程-id" tabindex="-1">什么是进程 ID? <a class="header-anchor" href="#什么是进程-id" aria-label="Permalink to “什么是进程 ID?”">​</a></h3><p>PID 代表<ruby>进程标识号<rt>process identification</rt></ruby>，它在大多数操作系统内核（如 Linux、Unix、macOS 和 Windows）中使用。它是在操作系统中创建时自动分配给每个进程的唯一标识号。一个进程是一个正在运行的程序实例。</p>',5)),i("p",null,[s[1]||(s[1]=i("strong",null,"建议阅读：",-1)),s[2]||(s[2]=a()),n(e,{href:"https://www.2daygeek.com/check-find-apache-httpd-web-server-uptime-linux/"},{default:p(()=>[...s[0]||(s[0]=[a("如何查看 Apache Web 服务器在 Linux 中的运行时间",-1)])]),_:1})]),s[17]||(s[17]=t(`<p>除了 init 进程外其他所有的进程 ID 每次都会改变，因为 init 始终是系统上的第一个进程，并且是所有其他进程的父进程。它的 PID 是 1。</p><p>PID 默认的最大值是 <code>32768</code>。可以在你的系统上运行 <code>cat /proc/sys/kernel/pid_max</code> 来验证。在 32 位系统上，<code>32768</code> 是最大值，但是我们可以在 64 位系统上将其设置为最大 2^22（约 4 百万）内的任何值。</p><p>你可能会问，为什么我们需要这么多的 PID？因为我们不能立即重用 PID，这就是为什么。另外为了防止可能的错误。</p><p>系统正在运行的进程的 PID 可以通过使用 <code>pidof</code>、<code>pgrep</code>、<code>ps</code> 和 <code>pstree</code> 命令找到。</p><h3 id="方法-1-使用-pidof-命令" tabindex="-1">方法 1：使用 pidof 命令 <a class="header-anchor" href="#方法-1-使用-pidof-命令" aria-label="Permalink to “方法 1：使用 pidof 命令”">​</a></h3><p><code>pidof</code> 用于查找正在运行的程序的进程 ID。它在标准输出上打印这些 id。为了演示，我们将在 Debian 9（stretch）系统中找出 Apache2 的进程 ID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pidof apache2</span></span>
<span class="line"><span>3754 2594 2365 2364 2363 2362 2361</span></span></code></pre></div><p>从上面的输出中，你可能会遇到难以识别进程 ID 的问题，因为它通过进程名称显示了所有的 PID（包括父进程和子进程）。因此，我们需要找出父 PID（PPID），这是我们要查找的。它可能是第一个数字。在本例中，它是 <code>3754</code>，并按降序排列。</p><h3 id="方法-2-使用-pgrep-命令" tabindex="-1">方法 2：使用 pgrep 命令 <a class="header-anchor" href="#方法-2-使用-pgrep-命令" aria-label="Permalink to “方法 2：使用 pgrep 命令”">​</a></h3><p><code>pgrep</code> 遍历当前正在运行的进程，并将符合选择条件的进程 ID 列到标准输出中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pgrep apache2</span></span>
<span class="line"><span>2361</span></span>
<span class="line"><span>2362</span></span>
<span class="line"><span>2363</span></span>
<span class="line"><span>2364</span></span>
<span class="line"><span>2365</span></span>
<span class="line"><span>2594</span></span>
<span class="line"><span>3754</span></span></code></pre></div><p>这也与上面的输出类似，但是它将结果从小到大排序，这清楚地说明父 PID 是最后一个。在本例中，它是 <code>3754</code>。</p><p><strong>注意：</strong> 如果你有多个进程的进程 ID，那么在使用 <code>pidof</code> 和 <code>pgrep</code> 识别父进程 ID 时就可能不会很顺利。</p><h3 id="方法-3-使用-pstree-命令" tabindex="-1">方法 3：使用 pstree 命令 <a class="header-anchor" href="#方法-3-使用-pstree-命令" aria-label="Permalink to “方法 3：使用 pstree 命令”">​</a></h3><p><code>pstree</code> 将运行的进程显示为一棵树。树的根是某个 pid，如果省略了 pid 参数，那么就是 init。如果在 <code>pstree</code> 命令中指定了用户名，则显示相应用户拥有的所有进程。</p><p><code>pstree</code> 会将相同的分支放在方括号中，并添加重复计数的前缀来可视化地合并到一起。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pstree -p | grep &quot;apache2&quot;</span></span>
<span class="line"><span> |- apache2(3754) -|-apache2(2361)</span></span>
<span class="line"><span> | |-apache2(2362)</span></span>
<span class="line"><span> | |-apache2(2363)</span></span>
<span class="line"><span> | |-apache2(2364)</span></span>
<span class="line"><span> | |-apache2(2365)</span></span>
<span class="line"><span> | \`-apache2(2594)</span></span></code></pre></div><p>要单独获取父进程，请使用以下格式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pstree -p | grep &quot;apache2&quot; | head -1</span></span>
<span class="line"><span> |- apache2(3754) -|-apache2(2361)</span></span></code></pre></div><p><code>pstree</code> 命令非常简单，因为它分别隔离了父进程和子进程，但这在使用 <code>pidof</code> 和 <code>pgrep</code> 时命令不容易做到。</p><h3 id="方法-4-使用-ps-命令" tabindex="-1">方法 4：使用 ps 命令 <a class="header-anchor" href="#方法-4-使用-ps-命令" aria-label="Permalink to “方法 4：使用 ps 命令”">​</a></h3><p><code>ps</code> 显示活动进程的选择信息。它显示进程 ID（<code>pid</code>=PID）、与进程关联的终端（<code>tname</code>=TTY）、以 <code>[DD-]hh:mm:ss</code> 格式（<code>time</code>=TIME）显示的累计 CPU 时间、以及执行名（<code>ucmd</code> = CMD）。输出默认是未排序的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ps aux | grep &quot;apache2&quot;</span></span>
<span class="line"><span>www-data 2361 0.0 0.4 302652 9732 ? S 06:25 0:00 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>www-data 2362 0.0 0.4 302652 9732 ? S 06:25 0:00 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>www-data 2363 0.0 0.4 302652 9732 ? S 06:25 0:00 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>www-data 2364 0.0 0.4 302652 9732 ? S 06:25 0:00 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>www-data 2365 0.0 0.4 302652 8400 ? S 06:25 0:00 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>www-data 2594 0.0 0.4 302652 8400 ? S 06:55 0:00 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>root 3754 0.0 1.4 302580 29324 ? Ss Dec11 0:23 /usr/sbin/apache2 -k start</span></span>
<span class="line"><span>root 5648 0.0 0.0 12784 940 pts/0 S+ 21:32 0:00 grep apache2</span></span></code></pre></div><p>从上面的输出中，我们可以根据进程的启动日期轻松地识别父进程 ID（PPID）。在此例中，apache2 启动于 <code>Dec 11</code>，它是父进程，其他的是子进程。apache2 的 PID 是 <code>3754</code>。</p><hr>`,25)),i("p",null,[s[4]||(s[4]=a("via: ",-1)),n(e,{href:"https://www.2daygeek.com/how-to-check-find-the-process-id-pid-ppid-of-a-running-program-in-linux/"},{default:p(()=>[...s[3]||(s[3]=[a("https://www.2daygeek.com/how-to-check-find-the-process-id-pid-ppid-of-a-running-program-in-linux/",-1)])]),_:1})]),i("p",null,[s[8]||(s[8]=a("作者：",-1)),n(e,{href:"https://www.2daygeek.com/author/magesh/"},{default:p(()=>[...s[5]||(s[5]=[a("Magesh Maruthamuthu",-1)])]),_:1}),s[9]||(s[9]=a(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[6]||(s[6]=[a("geekpi",-1)])]),_:1}),s[10]||(s[10]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[13]||(s[13]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:p(()=>[...s[12]||(s[12]=[a("Linux中国",-1)])]),_:1}),s[15]||(s[15]=a(" 荣誉推出",-1))])])}const m=d(c,[["render",h]]);export{P as __pageData,m as default};
